    body: "「3歳児神話」とは、「子どもが3歳になるまでは母親が家庭でつきっきりで育てるべきであり、そうしなければ子どもの発達に悪影響が及ぶ」とする社会的な通念を指す言葉です。高度経済成長期以降、日本社会に広く浸透してきた考え方とされています。\n\nしかし1998年版の厚生白書（当時）は、3歳児神話について「合理的な根拠は認められない」との見解を示しました。発達心理学の研究においても、子どもの健やかな発達にとって重要なのは、母親であるかどうかよりも、特定の大人との継続的で応答的な関わり（アタッチメント）の質であるとされています。\n\nこの検証は、保育所等を利用しながら働く保護者への不安や社会的な偏見を和らげる根拠として参照されるとともに、育児担当制保育のように、保育所においても安定した愛着関係を築く工夫が重要であるという理解を後押ししています。",
