    body: "幼児期における非認知能力の育成とは、IQのように数値で測定できる認知能力に対し、自制心、粘り強さ、意欲、協調性、自己肯定感といった数値化しにくい力（非認知能力）を、幼児期の遊びや生活の中で育てようとする保育実践上の取り組みを指します。\n\n幼稚園教育要領などが重視する「遊びを通しての総合的な指導」や「見守る保育」の考え方は、子どもが試行錯誤しながら自ら物事に取り組む経験を保障するものであり、非認知能力を育む具体的な保育方法として捉えられています。異年齢保育やドキュメンテーションによる子ども理解も、こうした力を可視化し支える手立てとして活用されます。\n\nこの視点は、経済学者ジェームズ・ヘックマンによる就学前教育の効果研究とも結びついており、幼児期の保育実践と、その社会的・経済的意義を論じる研究がともに参照される分野となっています。",
