    body: "5領域とは、幼稚園教育要領・保育所保育指針・幼保連携型認定こども園教育・保育要領に共通して示されている、幼児教育のねらい及び内容を整理するための5つの視点である。「健康」は心身の健康に関する領域、「人間関係」は他者との関わりに関する領域、「環境」は身近な環境との関わりに関する領域、「言葉」は言葉の獲得に関する領域、「表現」は感性と表現に関する領域を指す。小学校以降の教科のように独立して指導されるものではなく、遊びを中心とした生活の中で、5つの領域の内容が相互に関連し合いながら総合的に育まれる点が特徴である。\n\n各領域には「ねらい」と「内容」が示されており、保育者はこれらを踏まえて環境を構成し、子どもの自発的な活動としての遊びを通して指導を行う。例えば、砂場での泥だんご作りという一つの遊びの中にも、身体を使う「健康」、友達と協力する「人間関係」、素材の性質に気づく「環境」、やりとりする「言葉」、工夫して形にする「表現」といった複数の領域のねらいが同時に含まれている。\n\n2017年改訂の要領・指針では、5領域に加えて「幼児期の終わりまでに育ってほしい姿」（10の姿）が新たに示され、5領域で育まれた資質・能力が就学時にどのような具体的な姿として表れるかを示す形で、幼小接続の観点からの整理も進められている。",
