    body: "保育教諭は、2015年の子ども・子育て支援新制度の施行に伴い創設された、幼保連携型認定こども園に配置される職員の職名である。就学前の子どもに対する教育及び保育を一体的に担うという幼保連携型認定こども園の性格を反映し、原則として幼稚園教諭免許状と保育士資格の両方を併有することが求められる。\n\nもっとも、制度創設時点では両方の免許・資格を有する人材が限られていたことから、改正認定こども園法の施行後一定期間は、いずれか一方の免許・資格のみでも保育教諭となることができる経過措置が設けられた。この経過措置は度重なる延長を経て、令和11年度末までとされている。あわせて、幼稚園や保育所等での勤務経験を評価し、大学等における必要単位数を軽減する特例制度も設けられており、免許・資格の併有を促進する仕組みが整備されている。\n\n保育教諭の存在は、従来分かれていた幼稚園教諭と保育士という2つの専門職を、就学前教育・保育の一体的な提供という観点から接続する試みであり、幼保一元化をめぐる政策動向を象徴する制度の一つとして位置づけられる。",
