    kana: "ひ",
    categories: ["early-childhood"],
    summary:
      "病気の回復期にあり集団保育が難しいが、保護者の就労等により家庭での保育も困難な子どもを、専用施設等で一時的に預かる保育サービス。",
    body: "病後児保育は、病気の急性期は過ぎたものの、まだ集団保育を受けるには体力が回復しきっていない子どもを対象に、保護者が働いている等の理由で家庭での保育が困難な場合に、専用のスペースや看護師等を配置した施設で一時的に預かる事業である。病気の急性期にある子どもを対象とする「病児保育」に対し、病後児保育は回復期の子どもを対象とする点で区別される。実際には両者を合わせて「病児・病後児保育」として一体的に運営されることも多い。\n\n実施施設には、病院・診療所に併設される医療機関併設型、保育所に併設される保育所併設型などの類型があり、看護師や保育士が配置され、子どもの体調管理や与薬対応を行いながら保育が行われる。利用には事前登録や医師の意見書の提出が必要となる場合が一般的である。\n\n共働き家庭の増加に伴い、子どもの病気回復期における預け先の確保は保護者の就労継続にとって切実な課題となっており、病後児保育は仕事と育児の両立支援策の一つとして子ども・子育て支援新制度の地域子ども・子育て支援事業に位置づけられている。一方で、実施施設数が地域によって限られていることや、当日の急な利用ニーズに対応しきれないことなど、供給面での課題も指摘されている。",
