    body: "アプローチカリキュラムとは、就学前の5歳児が円滑に小学校の生活や学習へ適応できるようにするとともに、幼児期に育まれた学びが小学校の生活や学習に生かされ、連続していくよう工夫された、幼稚園・保育所・認定こども園における接続期のカリキュラムである。多くの自治体では5歳児クラスの後半、おおむね1月から3月ごろの時期を対象に編成される。\n\n具体的には、当番活動や係活動を通じた役割意識の育成、時間や決まりを意識した集団活動、小学校の教室や授業を体験する交流活動など、遊びを中心とした従来の保育内容に加え、小学校生活を意識した活動が段階的に取り入れられる。この際、幼稚園教育要領等が示す「幼児期の終わりまでに育ってほしい姿」が、保育者が育ちを見取り、小学校の教員に伝える際の共通の視点として活用される。\n\nアプローチカリキュラムは、小学校側で編成されるスタートカリキュラムと対をなす概念であり、両者が接続することで、就学前から小学校低学年にかけての学びと育ちの連続性が確保される。文部科学省とこども家庭庁が共同で進める「幼保小の架け橋プログラム」においても、市区町村単位でアプローチカリキュラムとスタートカリキュラムを一体的に検討することが推進されている。",
