    summary:
      "幼児期の教育と小学校教育とを円滑につなぐための考え方や取り組み全般を指す用語。カリキュラムの接続、教員の相互理解、子どもの発達の連続性の確保などを含む。",
    body: "幼小接続とは、幼稚園・保育所・認定こども園における幼児期の教育・保育と、小学校教育とを円滑に接続させるための考え方及び取り組み全般を指す用語である。幼児期の教育は遊びを通した総合的な指導を基本とするのに対し、小学校教育は教科ごとの系統的な学習を基本とするため、両者の間には指導方法や生活環境に大きな違いがある。この段差を緩和し、子どもの発達と学びの連続性を確保することが幼小接続の目的である。\n\n幼小接続の具体策としては、5歳児が小学校生活へ移行するための「アプローチカリキュラム」と、小学校入学後に幼児期の学びを生かす「スタートカリキュラム」の編成、保育者と小学校教員が互いの保育・授業を参観し合う合同研修や交流活動、「幼児期の終わりまでに育ってほしい姿」を共通言語とした指導要録・保育要録の送付などが挙げられる。国は「幼保小の架け橋プログラム」を通じて、市区町村単位でこうした取り組みを推進している。\n\n幼小接続が不十分な場合、入学後の児童が集団行動になじめず授業が成立しにくくなる、いわゆる「小1プロブレム」につながることが指摘されており、幼小接続は子どもの円滑な学びの移行という発達的観点と、学級運営の安定という学校経営的観点の双方から重要視されている政策課題である。",
    relatedSlugs: ["start-curriculum", "approach-curriculum", "shogaku1-problem", "sodachite-hoshii-sugata"],
    isCanonical: true,
    tags: ["幼保小接続", "幼保小の架け橋プログラム", "発達の連続性"],
