    body: "小1プロブレムとは、小学校に入学したばかりの1年生の児童が、集団生活や授業のルールになじめず、教室内を歩き回る、私語が止まらない、教員の指示に従えないといった状態が数か月にわたって続き、学級運営に支障をきたす現象を指す。1990年代末から2000年代にかけて日本各地の小学校で顕在化し、教育現場や研究者の間で広く認知されるようになった用語である。\n\n背景としては、遊びを中心とした自由度の高い幼児期の生活から、時間割に基づく規律的な学校生活への急激な環境変化に子どもが適応しきれないことが指摘される。加えて、少子化に伴うきょうだい関係の希薄化や、地域における異年齢での遊び集団の減少により、子どもが集団のルールや我慢を学ぶ経験が減っていることも一因として論じられてきた。中学校進学時に同様の不適応が生じる「中1ギャップ」と並んで語られることもある。\n\n小1プロブレムへの対応策として、幼児期の育ちを踏まえたスタートカリキュラムの導入、幼稚園・保育所と小学校との交流や合同研修による相互理解の促進、入学当初における学級担任の複数配置や生活支援員の活用などが進められている。単なる子どもの問題行動として捉えるのではなく、幼児教育と小学校教育の接続の在り方そのものを見直す契機として位置づけられている点が重要である。",
