    body: "共同注意（joint attention）とは、自分と他者が同じ対象に注意を向け、その状態を互いに認識し合うことを指す発達心理学の概念である。生後9か月前後に、それまでの自分と物、あるいは自分と人という二者関係（二項関係）から、自分・他者・対象物という三者による三項関係へと子どもの認知が発達することで成立するとされ、この時期は「9か月革命」とも呼ばれる。\n\n共同注意の代表的な行動として、他者が見ている方向を追って自分も視線を向ける「視線追従」、興味のある対象を指さして他者に伝えようとする「指さし」、大人が示した物を自分も見ようとする、あるいは逆に自分が見ている物を大人にも見せようとする行動などが挙げられる。指さしには、自分の欲しい物を要求する「要求の指さし」と、興味や発見を他者と共有しようとする「叙述の指さし」があり、後者は特に社会性やコミュニケーション能力の発達との関連が深いとされる。\n\n共同注意は、他者と対象について注意や情動を共有する体験を通して、言葉の意味を学習する土台となるほか、他者の心の状態を推測する心の理論の発達にもつながる重要な能力とされる。自閉スペクトラム症のある子どもでは共同注意の成立に遅れや特徴が見られることが多く報告されており、乳幼児期の発達支援の場面でも重要な観察・評価の視点となっている。",
