    body: "人見知りとは、生後6か月前後から1歳半頃にかけて多くの乳児に見られる、見知らぬ人物に対して不安や警戒を示す行動を指す。それまで誰に対しても比較的穏やかに反応していた乳児が、特定の養育者（多くは母親）以外の人物に近づかれると、泣き出したり、顔を背けたり、養育者にしがみついたりするようになる。発達心理学では、人見知りは乳児が特定の養育者を他の人物と区別して認識できるようになったこと、すなわち愛着（アタッチメント）が形成されつつあることの現れとして肯定的に位置づけられる。\n\n人見知りは、乳児の認知発達において、見慣れた対象と見慣れない対象を区別する識別能力が育ってきたことも示している。多くの場合、生後8か月から10か月頃に最も強く現れ、その後、養育者以外の人物との関わりの経験を重ねる中で徐々に和らいでいく。人見知りの強さや現れ方には個人差が大きく、気質的な要因や養育環境によっても異なる。\n\n保育の場面では、入園当初の乳児が保育者に人見知りを示すことは発達上自然な現象であり、無理に接触を迫るのではなく、養育者との分離不安にも配慮しながら、乳児が安心できる関係を少しずつ築いていく緩やかな受け入れ（慣らし保育）が重要とされる。人見知りは、生後間もない時期から養育者との間に築かれてきた愛着関係の発達的な表れとして理解される。",
