    body: "イヤイヤ期は、発達心理学でいう「第一次反抗期」に相当し、おおむね1歳半頃から3歳頃までの幼児に見られる、自己主張の強まりを特徴とする発達段階である。それまで養育者の働きかけに比較的従順であった子どもが、着替えや食事、外出の場面などで「イヤ」「自分でやる」と繰り返し反発し、大人の意図通りに物事が進まなくなることから、日本では俗に「イヤイヤ期」と呼ばれる。\n\nこの時期の反抗は、子どもの自我（自分は他者とは異なる独立した存在であるという意識）が急速に発達し、自分の意思で行動したいという欲求が高まる一方で、それを適切に言語化したり感情を調整したりする力がまだ十分に育っていないために生じるとされる。発達心理学者エリクソンの心理社会的発達理論においても、この時期は「自律性 対 恥・疑惑」の危機にあたり、自分で物事を行おうとする自律性の感覚を獲得する重要な段階として位置づけられている。\n\n保育や子育ての実践においては、イヤイヤ期の反抗を単なる困った行動として抑え込むのではなく、子どもの自我の育ちを支える発達過程として肯定的に捉えることが重要とされる。子どもの気持ちを言葉で受け止めながら、安全の範囲内で本人の選択や試行錯誤を尊重する関わりが、情動の自己調整力や自立心の発達を促すとされ、幼稚園教育要領等が重視する「自立心」の育ちとも関連する時期である。",
