    categories: ["early-childhood"],
    summary:
      "森や野山、海辺など自然の中を主な保育の場とする、欧州発祥の保育・幼児教育の形態。日本では自治体の認証・認定制度の整備が進んでいる。",
    body: "森のようちえんは、園舎に頼らず、あるいは園舎を補助的に使いながら、森や里山などの自然の中で日常の保育を行う取り組みです。欧州発祥とされ、デンマークを起源とする説明が多く見られますが、始まった年代は資料により異なり、はっきり断定することはできません。日本では、自然保育、野外保育などと呼ばれることもあります。\n\n日本では、認可の幼稚園・保育所のほか、NPOや認可外の団体など多様な運営形態があります。質を公的に担保するため、長野県が2015年に自然保育の認定制度を設け、広島県と鳥取県が2017年にそれぞれ自然保育の認証制度を設けました。2015年には日本自然保育学会も設立されています。\n\n自然の中での遊びは、五感を使った体験や、身体を使った遊び、危険を自分で察知して避ける力の育ちにつながると期待されています。一方で、天候や野生動物、水辺などのリスクがあるため、安全管理の研修や、遊びの価値を損なわない範囲でのリスクとハザードの区別が課題とされます。",
