    body: "ファミリー・サポート・センター事業は、育児の援助を受けたい人（利用会員）と、援助を行いたい人（提供会員）を会員とし、センターが両者の連絡・調整を行う仕組みです。正式には「子育て援助活動支援事業（ファミリー・サポート・センター事業）」と呼ばれ、子ども・子育て支援法に基づく地域子ども・子育て支援事業の一つに位置づけられています。\n\n実施主体は市区町村で、運営は社会福祉協議会やNPOなどに委託されることが多くあります。援助の内容は、保育施設への送り迎え、保育施設の終了後や学校の放課後の預かり、冠婚葬祭や急な用事の際の預かりなどで、利用会員から提供会員へ謝礼が支払われます。こども家庭庁が所管しています。\n\nこの事業は、保育所や幼稚園の利用だけでは対応しきれない短時間・臨時の需要を、地域の相互扶助で補う点に特徴があります。一方で、提供会員の確保や研修、事故防止の体制づくりが課題であり、災害時には柔軟な対応が自治体に求められた例もあります。",
