    body: "認可外保育施設とは、児童福祉法に基づく認可（認定こども園・保育所など）を受けていない保育施設の総称で、ベビーホテル、事業所内保育施設、いわゆる認証保育所の類などを含みます。児童福祉法により、設置後1か月以内に都道府県知事等へ届け出ることが義務づけられ、国の指導監督基準に基づいて立入調査などの指導監督を受けます。\n\n2019年10月に始まった幼児教育・保育の無償化では、認可外保育施設も、届出をし、市区町村から「確認」を受けることで対象となりました。当初は5年間（2024年9月30日まで）の経過措置があり、基準を満たしていない施設でも確認を受けていれば原則として対象でした。2024年10月以降は、基準を満たす旨の証明書の交付を受けた施設が対象となり、基準を満たさない施設の扱いについても別途通知で猶予期間が示されています。\n\n認可外保育施設は、夜間・長時間の保育や少人数のきめ細かな保育など多様なニーズに応える一方、重大事故が起きやすいとの指摘もあり、事故防止や保育の質の確保が課題となっています。保護者が施設の基準適合状況を確認できる情報公開も重視されています。",
