    body: "利用者支援事業は、子ども・子育て支援新制度のもとで、子どもや保護者、妊産婦が、教育・保育施設や地域の子育て支援事業、保健・医療・福祉などの関係機関を円滑に利用できるよう支援する事業です。身近な場所で相談に応じ、情報を提供し、必要なサービスにつなぎます。\n\n類型は、基本型、特定型、母子保健型の3つで整理されてきました。基本型は行政窓口以外の身近な施設で継続的に相談を受けるもの、特定型は主に市町村窓口で保育サービスの利用を支援するもので「保育コンシェルジュ」と呼ばれます。母子保健型は保健師などが妊産婦や乳幼児の保健面を支援するもので、2024年度からはこども家庭センター型として整理されています。\n\n保育の利用が多様化し、制度が複雑になるなか、保護者が自分に合ったサービスを選べるようにする役割があります。支援者には、地域の資源を把握し、関係機関と連携して継続的に支える力が求められます。",
