    body: "保育所保育指針では、各保育所が保育の方針や目標に基づき、子どもの発達過程を見通して、保育の全体像を示す計画を編成することとされています。この計画は、2008年の改定で従来の「保育計画」から「保育課程」に改められ、2017年告示の指針では「全体的な計画」と呼ばれています。背景には、保育所内にさまざまな計画が存在し、保育計画の位置づけが曖昧であるという課題がありました。\n\n全体的な計画に基づいて、具体的な保育を行うために作成するのが指導計画です。年間・期・月といった長期的な計画と、週・日などの短期的な計画があり、子どもの生活や発達を見通しながら、ねらいや環境構成、保育者の援助を具体的に考えます。保健計画や食育計画も、全体的な計画と関連づけて作成されます。\n\n計画は一度つくれば終わりではなく、実践、記録、振り返り、改善というサイクルのなかで見直されます。2008年の改定では、保育課程や指導計画に基づく保育実践を自己評価することも規定されました。保育者の省察や、カリキュラム・マネジメントの考え方とも通じています。",
