    body: "幼児教育は、幼稚園、保育所、認定こども園など施設の種類が分かれているため、地域全体で質を支える仕組みが求められてきました。そこで、自治体に幼児教育の推進の拠点として「幼児教育センター」を置き、施設類型を問わず研修や相談に当たる人材として「幼児教育アドバイザー」を配置する体制づくりが進められています。\n\n文部科学省は、2016〜2018年度に「幼児教育推進体制構築事業」を委託事業として実施し、都道府県を中心とする自治体の取り組みを後押ししました。その後も、アドバイザーに求められる資質・能力や研修の例を示すなど、推進体制の充実が図られています。文部科学省の資料によれば、令和5年度の幼児教育実態調査で、アドバイザーを配置している自治体は、都道府県で91.5％、市町村で47.5％とされています。\n\nアドバイザーは、保育現場を訪れて保育を見たうえで助言したり、研修を企画したりします。幼稚園教育要領や保育所保育指針に共通する幼児教育の考え方を広めるとともに、小学校との接続（架け橋プログラム）を支える役割も期待されています。",
