    summary:
      "スイスの生物学者ポルトマンが、人間の新生児は他の高等哺乳類より未熟な状態で生まれるとして唱えた概念。誕生後の最初の1年の養育環境の重要性を示す。",
    body: "ポルトマン（Adolf Portmann）はスイスの生物学者で、人間の新生児が他の高等哺乳類に比べて未熟な状態で生まれることを「生理的早産」と呼びました。多くの哺乳類の子は、生まれてすぐに立って歩ける離巣性（巣立ち型）ですが、人間は無力な状態で生まれる就巣性（巣ごもり型）に近く、ただし本来は離巣性に近い形態をもつため、二次的就巣性と特徴づけられます。\n\nポルトマンは、人間が本来はもう1年ほど母胎にいてもよいはずの状態で生まれてくると考え、誕生後の約1年を、胎外で過ごす「子宮外の胎児期」のように捉えました。その間、人間は社会的な環境のなかで、いわば「社会的子宮」に包まれて育つとされます。日本語版の『人間はどこまで動物か』は、1961年に岩波新書として刊行されました。\n\n保育の分野では、乳児が安心できる大人との応答的な関わりを必要とする根拠として引用されます。愛着形成や育児担当制保育、乳児保育の重要性を考える際の背景知識となる概念です。",
