    body: "心理学者・鯨岡峻らによって提唱された、保育や子育ての現場における質的な記録・省察の手法である。子どもの行動をチェックリストなどで客観的・数値的に測定するのではなく、特定の場面において子どもと保育者の間に何が起こり、互いにどう感じたかを文脈を含めて生き生きとした文章で記述する。\n\n単なる行動観察記録にとどまらず、その時の子どもの表情、言葉、身体の動きとともに、それを見守る保育者自身の感情の動きや葛藤、気づきまでも主観的に包み隠さず書き留める点に特徴がある。\n\n園内研修やカンファレンスにおいてエピソード記述を共有・検討することで、同僚保育者とともに子どもの内面世界や意味世界を深く共感的に理解することが可能となる。保育者の専門的省察を促し、保育の質を向上させる優れたツールとして定着している。",
