    reading: "ぼしけんこうてちょうとにゅうようじけんこうしんさ",
    kana: "ほ",
    categories: ["early-childhood"],
    summary:
      "母子保健法に基づき交付され妊娠・出産から乳幼児期の発育を記録する手帳と、1歳6か月児・3歳児等の節目に自治体が義務的に実施する健康診査。",
    body: "母子保健法に基づき市町村から交付される「母子健康手帳」と、同法に規定される「乳幼児健康診査」は、子どもの健康と健全な発達を公的に支える母子保健制度の柱である。母子健康手帳は、母体の妊娠・出産経過から子どもの予防接種歴、発育・発達の経過を長期間にわたり一元的に記録・管理する。\n\n乳幼児健康診査は、市町村に実施義務がある「1歳6か月児健康診査」および「3歳児健康診査」をはじめ、各自治体で乳児期に実施される。身体計測、小児科医・歯科医による診察、発達状況の確認、育児不安の相談などを総合的に行う。\n\n身体的疾患や発達障害などの早期発見・早期支援の機会となるだけでなく、保護者の孤立や虐待リスクを早期に把握・予防するセーフティネットとしても極めて重要な役割を果たしている。",
