    body: "倉橋の誘導保育論は、明治期以来の恩物を用いた注入主義的・形式的な保育を克服し、子どもの生活そのものを保育の中心に据える思想として大正期から昭和初期にかけて確立された。子どもが生まれ持っている自発的な自己活動の力を根底から信頼し、画一的な教え込みではなく内発的な意欲を引き出すことを保育の基本原理とした。\n\n園の実践においては、保育者はあらかじめ固定された指導案を一方的に課すのではなく、子どもの興味や自発的欲求を綿密に観察して活動を豊かに展開させる環境を構成する。子どもが自己の生活に没頭する中で、保育者は過度な介入を避けつつ、共感的な眼差しや適切な言葉かけによって子どもの自己活動を次の段階へと自然に誘導する。\n\nこの誘導保育の理念は、現行の幼稚園教育要領や保育所保育指針が掲げる「環境を通して行う教育」の根底を形成している。小学校教育への円滑な接続を見据えつつ、幼児期に自己を発揮して主体的に生活を創り出す経験を重ねることは、生涯にわたる自律的な学びの確かな基礎を築くものとして高く評価される。",
