    body: "倉橋による1926年刊行の『幼稚園真諦』は、日本の幼児教育史における不朽の名著として知られ、保育の本質を問い直した著作である。学校教育の予備段階として知識を詰め込む当時の風潮を批判し、幼児期独自の生活の価値を認めて「育てて育てる」という育ちの相互性を保育の根本原理として提示した。\n\n園の現場において『幼稚園真諦』の思想は、子どもが現在を最もよく生きることを最優先とする保育実践へと具体化される。保育者は子どもを大人の縮図として扱わず、子どもの目線に立って遊びの動機や生活の文脈を深く理解し、子ども自らが充実感を味わえるような温かい人間関係と安全な空間を整える援助を展開する。\n\n現代の幼児教育指針においても、幼児期にふさわしい生活の展開や情緒の安定を重視する視点は『幼稚園真諦』の本質論に直結している。小学校教育との接続においても、無理な早期学習ではなく自発的な活動を通じた豊かな心情や探究心の醸成が何よりも大切であるという警鐘と示唆を今なお与え続けている。",
