    body: "幼稚園令は1926年に大正天皇の勅令として公布された日本初の幼稚園単独法令である。それまで小学校令施行規則などの下位規定に位置づけられていた幼稚園を独立した教育施設として法的に公認し、初等教育の予備ではなく幼児期特有の心身の発達を助長することを固有の目的として明確に規定した。\n\n本令では、保育項目として「遊戯」「唱歌」「談話」「手作業」の4項目が明定され、保育時間や園児定員、設備基準などの枠組みが整備された。園現場ではこれらに基づき、画一的な注入教育を避け、幼児の身体と精神の調和的な発達を促す生活中心の環境構成や指導計画が組織的に立案されるようになった。\n\n幼稚園令の制定は、日本の幼児教育が制度的にも思想的にも自立を果たす契機となった。戦後の学校教育法第77条における幼稚園の目的規定や幼稚園教育要領の枠組みへと受け継がれ、現在の就学前教育の普遍化に向けた歴史的な土台を形成した。",
