    body: "恩物は、幼稚園の創始者フレーベルが考案した幼児のための体系的な遊具群である。神が創造した宇宙の秩序を象徴するものとして構想され、球や立方体、円柱などの幾何学的立体から面、線、点へと順次抽象化していく全20種の段階的構成を通じて、子どもの精神的発達と認識力を高める意図を持っていた。\n\n園における指導では、第1恩物の毛糸の球から始まり、分割された木製立方体である第3恩物から第6恩物を用いた建築遊びへと発展させる。子どもは恩物を手で触れ、組み立て、分解する活動を通して、形態や数量、空間的な調和の法則を遊びの中で感覚的・直観的に体得していった。\n\n恩物は世界中に普及し、現代の積み木や構成玩具の原型となった。明治期の日本でも導入されたが、やがて形式的な教え込みに陥った反省から生活中心の保育への転換を促す契機ともなった。遊びを通した直観教育の重要性を世界に示した歴史的遺産として今なお評価される。",
