    body: "ドイツの教育思想家フレーベルは、1826年の主著『人間の教育』において、万物の中に神性が宿るという人間観を展開した。幼児期における遊びは単なる気晴らしや身体の運動ではなく、子ども自身の内面的な生命力や神性が自発的に外へと表出される最も神聖な精神活動であると位置づけた。\n\n園の実践においてフレーベルは、大人が外側から知識や規律を強制する干渉的な教育を厳しく戒め、子どもの内なる育ちを保護し追随する「受動的・追随的教育」を提唱した。保育者は自然豊かな環境を整え、子どもが自由に遊びに打ち込めるように寄り添い、その探究活動を温かく見守る援助手順を重視した。\n\n遊びの神聖性という理念は、現代の幼児教育指針における「遊びを通して総合的に指導する」という根本原則の直接的な思想的源流となった。子どもの内発的動機や主体性を無条件に肯定する姿勢は、小学校以降の学習意欲の土台となり、現代社会における子どもの権利尊重の思想とも共鳴している。",
