    body: "イタリアの女性医師・教育者モンテッソーリは、生物学の概念を人間の発達に応用し「敏感期」の理論を確立した。乳幼児期には秩序、感覚、言語、運動など特定の機能や能力を獲得するために特別な感受性が一時的に高まり、その対象に自発的に強く引きつけられる限られた時期が存在すると主張した。\n\n園における指導環境では、子どもが今どの敏感期にあるかを保育者が鋭く見極める観察が不可欠となる。秩序への強いこだわりを示す時期には物の配置や日課を一定に保ち、運動の敏感期には指先や全身を存分に動かせる教具を用意するなど、子どもの内的な発達要求に合致した環境を綿密に構成する援助が行われる。\n\n敏感期に適した刺激と活動を十分に保障された子どもは、深い集中状態を経て情緒的な充足と自立を獲得する。この時期の適切な援助は小学校以降の知的探究心や自己統制力の確固たる基盤を形成するため、現代の就学前教育において子どもの発達要求を正しく尊重する重要な理論的根拠となっている。",
