    body: "アトリエスタは、イタリア北部のレッジョ・エミリア市の乳幼児教育において独自に導入された芸術専門の指導者である。教育者マラグッツィの提唱に基づき、従来の学校教育における美術教師の枠組みを超えて、子どもの思考や感情の多様な表現形態を専門的な造形活動と探究によって保障するために制度化された。\n\n園のアトリエを中心に活動し、粘土、絵の具、紙、光と影、自然素材など多種多様なマテリアルを整備して環境を構成する。アトリエスタは技法を一方的に指導するのではなく、担任保育者と緊密に連携しながら子どもの発想や対話を観察し、プロジェクト活動の中で探究が深まるよう素材の提供や助言を行う。\n\nアトリエスタの存在は、子どもが言葉だけでなく造形や身体など多様な表現手段を駆使して自己を表現する権利を具現化している。日本の幼児教育における表現領域の指導法や表現活動の記録・省察に対しても、芸術と日常保育の融合という観点から多大な影響を与えている。",
