    body: "「子どもの100の言葉」は、レッジョ・エミリア教育の創始者ローリス・マラグッツィが自作の詩で表現した教育哲学の象徴である。近代の学校教育が言語や論理的思考ばかりを優先し子どもの豊かな可能性を奪ってきたと批判し、子どもは生まれながらに百通りの表現や思考の言葉を持っていると宣言した。\n\n園の現場では、絵の具や粘土による造形、歌や身体動作、光や影の実験、ごっこ遊びなど、あらゆる活動が子どもの対話や思考の重要な言葉として受容される。保育者は大人の価値観で正解を押しつけず、子どもの多様な表現を写真や発話記録などのドキュメンテーションによって可視化し、次の探究へとつなげる援助を展開する。\n\nこの教育哲学は、子どもを受動的な保護の対象ではなく自らの学びを創り出す権利主体として捉える現代の幼児教育観の確立に決定的な貢献を果たした。幼保小接続においても、点数化できない子どもの多様な表現力や感性を尊重し伸ばしていく教育の重要性を力強く示している。",
