    body: "英国の初期基礎段階（EYFS）は、0歳から5歳の就学前の子どもを対象として2008年に法制化された統一的な教育・保育基準である。保育所、幼稚園、小学校の就学前学級など施設の種類を問わず適用され、すべての子どもに最善のスタートを保障し教育格差を是正する福祉・教育政策の統合として創設された。\n\nEYFSは「個性ある子ども」「前向きな人間関係」「支援的な環境」「学習と発達」の4基本原則を掲げる。保育現場では、個人・社会・情緒的発達、身体発達、コミュニケーションと言語の主要領域を中心に、遊びを通した総合的な指導が展開され、保育者は観察記録に基づき一人ひとりの発達をきめ細かく援助する。\n\n5歳児修了時における到達度評価の作成を通じて、小学校初等教育への滑らかな接続が制度的に保障されている。公教育としての就学前教育の質を国全体で担保しつつ、子どもの健全な育ちと幼小接続の連続性を確保するモデルとして国際的な注目を集めている。",
