    body: "自然結びつき保育（森の幼稚園）は、1950年代にデンマークで一人の母親の実践から始まり、ドイツや北欧諸国、日本へと広がった野外保育運動である。人工的な園舎や遊具に頼らず、ありのままの自然を最大の教育環境と捉え、自然との共生を通じて子どもの全人的な発達と生命力を育むことを基本理念とする。\n\n園児たちは天候に関わらず毎日森や野山へ出かけ、一日中自然の中で過ごす。決まった遊具がないため、子どもたちは木の枝や石、泥や起伏のある地形そのものを見立てて遊びを創造する。保育者は危険を過剰に排除するのではなく、子どもの安全を見守りながら自発的な挑戦と仲間同士の協同を支える援助手順を徹底する。\n\n自然の中で五感を存分に使って活動する体験は、体力や平衡感覚だけでなく、危機管理能力、創造性、高い自己肯定感を育てる。小学校の生活科や理科、環境教育への確固たる土台となるだけでなく、現代社会における自然体験の喪失を補い子どもの心身の健康を保つ実践として国内外で高く支持されている。",
