    body: "発達心理学者エインズワースは、観察研究を通じて「安全基地」の概念を提唱した。乳幼児は信頼できる養育者を心の拠り所（安全基地）とすることで、未知の環境に対する恐怖や不安を克服し、周囲の世界を主体的に探索することができるという発達理論である。\n\n園における環境構成と援助では、子どもがいつでも戻ってこられる温かい居場所として保育者が存在することが求められる。子どもが新しい遊具や他者との関わりに踏み出す際、保育者は見守りの視線を送り、子どもが不安や挫折を感じて戻ってきたときには温かく受け止めて情緒を安定させる援助手順を繰り返す。\n\n保育者が確かな安全基地として機能することにより、子どもは自己効力感を高め、失敗を恐れずに多様な遊びや探究活動へと意欲を広げることができる。この探索行動の保障は、幼児期の主体的な学びを深化させ、小学校教育における知的好奇心や課題解決能力の確固たる源泉となる。",
