    body: "見立て遊び・つもり遊びとは、身近な玩具や素材を別の物に見立てたり、自らが特定の役割になったつもりで行動したりする象徴的な活動である。1歳代後半から現れる表象機能の発達に支えられ、子どもの想像力と精神的活動が飛躍的に深まる重要な発達段階として幼児教育指針でも中核に位置づけられる。\n\n保育現場では、形状が限定されない積み木や布、箱などの多様な素材を用意し、子どもの柔軟な発想を妨げない空間を構成する。保育者は子どもの世界観に共感的に寄り添い、「おいしいご飯ができたね」と応答することでイメージの共有と言語化を支え、無理に正解を押しつけず自主的な展開を援助する。\n\n現実の制約を離れて仮構の世界を創り出す経験は、抽象的思考力や感情の自己調整力を育む。仲間とイメージをすり合わせる協同的なごっこ遊びへの接続は、小学校以降の協調的学びや表現活動を支える確かな基盤となる。",
