    body: "幼児期の食育とは、食育基本法や保育所保育指針に基づき、子どもが日々の生活や遊びの中で食に関する関心と感謝の念を深め、健康な食生活の基礎を培う教育的取り組みである。野菜を自らの手で育てて食べる一連の直接体験は、自然の恵みや生命の尊厳を体感的に学ぶ機会となる。\n\n園の畑やプランターでは、ミニトマトやサツマイモなどの栽培を計画し、水やりや観察を日課とする。収穫時には野菜の感触や土の匂いを五感で確かめ、皮むきやちぎるなどの簡単な調理保育を導入して、子ども自身が主体的に食の準備に関われる環境を整える。\n\n苦手な食材も自ら育て調理することで進んで口にする意欲が芽生え、食への前向きな姿勢が育つ。自然の循環や生産者への感謝の心を養う体験は、小学校での生活科や理科、家庭科における食と健康に関する学びへの豊かな架け橋となる。",
