    body: "給食時の指導は、栄養補給にとどまらず、仲間や保育者と共に心地よく食事を味わう共食の場を通じて、基本的生活習慣と社会性を育む中核的な活動である。保育指針の「健康」および「人間関係」に関わる領域であり、無理な強制を避け、食べる意欲を尊重する指導思想が基本となる。\n\n保育室では、清潔で落ち着いた食卓を整え、適正な高さの机と椅子を配置して正しい姿勢を保持しやすい空間を作る。保育者は子どもの喫食量を個別に把握して無理のない配膳を行い、「いただきます」の挨拶や食具の正しい扱いを温かく示しながら、楽しい会話の場を醸成する。\n\n安心して美味しく食べる経験の積み重ねは、身体の健康だけでなく情緒的な充足感をもたらす。自他の食事のペースを尊重しマナーを守る態度は、就学後の学校給食や学級集団における円滑な適応を力強く支える。",
