    body: "排せつの自立支援とは、排尿感覚の自覚や身体機能の成熟と自己の生理的感覚の認知、言葉による意思表出が調和して成立する発達的支援である。かつての一斉指導や強制的な訓練を排し、子どもの個別発達リズムと心理的安心を第一に尊重する現代保育の重要課題である。\n\n園では、子どもの排尿間隔を丁寧に把握し、遊びの節目などで穏やかに声をかけて明るく清潔なトイレへ誘導する。足が床につく便座や手すりを整備して身体を安定させ、失敗した際も決してとがめたり責めたりせず、着替えを速やかに手伝いながら「出た感覚」を肯定的に受け止める援助を重ねる。\n\n自己の身体感覚を自己コントロールできる自信は、子どもの自立心と自己肯定感を飛躍的に高める。家庭と密接に連携しながら無理なく進める排せつの自立は、幼保小接続期における心理的な安心感と主体的な生活態度の根幹を形成する。",
