    body: "着脱の自立支援とは、衣服の脱ぎ着や靴の履き替え、脱いだ衣服をたたんで片づける一連の行為を子ども自身が行えるよう支える身辺自立の援助である。身体意識の獲得や運動機能の発達、生活環境への主体的な関わりを促す基本的生活習慣の柱として位置づけられる。\n\n園では、衣服の前後が分かりやすい印をつけたり、引き出しやカゴに分かりやすいマークを掲示して子どもが自発的に行動しやすい環境を構成する。保育者は全てを代行するのではなく、ボタンのかけ始めやズボンの引き上げなど要所のみをさりげなく介助し、自力でやり遂げる満足感を保障する。\n\n自分の身体と持ち物を主体的に整える経験は、生活全般に対する責任感と自信を育む。衣服の調整や身だしなみへの自立的態度は、小学校生活における時間管理や自己管理能力、規律ある生活態度の確固たる基盤となる。",
