      "午睡時の環境整備と突然死症候群の予防策とは、乳幼児の安全な睡眠を保障するため、仰向け寝の徹底や寝具・室温・換気の適切な管理を行い、乳幼児突然死症候群などの睡眠事故を未然に防ぐ保育上の重要対策である。",
    body: "午睡時の環境整備と突然死症候群の予防策は、保育所保育指針や国の睡眠事故予防指針に基づき、午睡中の重大事故を防ぎ子どもの尊い生命を守るための必須の保健安全施策である。睡眠中に乳幼児が予期せず死亡する乳幼児突然死症候群や窒息事故を防止するため、科学的知見に基づいた統一的な安全管理体制の構築が求められている。\n\n園の実践では、硬さのある平らな敷布団を用い、顔を覆う恐れのある掛け物やぬいぐるみ等を排除した安全な睡眠環境を整える。睡眠時は仰向け寝を基本とし、室内の温度や湿度、換気状態を適切に保ちながら、薄暗くしすぎず子どもの顔色や呼吸の動きを目視で即座に把握できる採光管理と静穏な環境づくりを徹底する。\n\n適切な睡眠環境の中で十分な休息をとることは、日中の活動への意欲を高め、心身の調和のとれた発達や主体的な生活リズムの形成を促す。小学校就学に向けた生活習慣の確立を支えるとともに、保護者に対しても安全な睡眠環境の大切さを伝え、家庭と園が一体となって子どもの健やかな育ちを支える基盤となる。",
