    body: "午睡チェックは、保育所保育指針や教育・保育施設等における事故防止ガイドラインに位置づけられた、午睡中の睡眠事故を防止するための厳格な見守り手順である。乳児期や幼児期の午睡中における突然の心肺停止や窒息を防ぐため、巡回観察を個人の勘に頼るのではなく、科学的基準に沿った組織的規程として運用することが定められている。\n\n保育現場では、0歳児を中心に5分間隔で子どもの胸や腹の上下運動を目視し、鼻先での呼吸音や息遣い、顔色、唇の色、発汗状態を直接確認する。触診により体温や脈拍の異常も点検し、睡眠チェック表に体位や時刻を正確に記録する。うつぶせ寝を発見した場合は即座に仰向けに戻し、安全な体位を保つよう援助する。\n\n全職員が共通の危機意識と点検手順を共有することは、安心安全な保育環境の根幹を支え、子どもが安心して休息できる基盤を保障する。健やかな休息によって培われた生命力と活動意欲は、日中の主体的・探究的な遊びを支え、生涯にわたる心身の健康と小学校生活への円滑な適応を力強く支える。",
