    body: "手洗い・うがい指導と感染予防習慣の形成は、幼稚園教育要領や保育所保育指針の「健康」領域に位置づけられ、集団生活における感染症の予防と健康な生活習慣の確立を目指す教育・保育活動である。他者と生活を共にする園生活において、病原体の感染経路を断ち、自他の生命と健康を守る基礎的生活習慣として重視されている。\n\n園では、外遊びの後や食事の前、排せつの後に、子どもが無理なく手洗いやうがいを行えるよう手洗い場の高さや動線を整える。指先や爪の間、手首までせっけんを泡立てて洗う手順を、歌やイラストを交えて楽しく体感できるよう援助する。うがい指導では水を含んで吐き出す動作から段階的にガラガラうがいへと導く。\n\n清潔を保つ心地よさを実感した子どもは、言われて行う受け身の姿勢から、自らの健康を守るために主体的に行動する態度を育む。この習慣は、小学校就学後の衛生管理や自己管理能力の土台となり、生涯を通じて自らの健康を適切に維持・向上させる基本的な生きる力の育成へとつながる。",
