    body: "歯磨き指導と幼児期の口内衛生管理支援は、学校保健安全法や保育所保育指針の健康領域に基づき、乳幼児期における虫歯や歯肉の疾患を予防し、健全な発育を支える保健教育である。乳歯の健康は永久歯の歯並びやかむ力、発音の発達に直結するため、園生活の中で正しい習慣を早期に定着させることが求められる。\n\n園では、昼食後や間食後に子どもが落ち着いて歯を磨ける環境を整え、歯ブラシの正しい持ち方や磨き方を歌や紙芝居等を用いて分かりやすく指導する。安全面を最優先し、歯ブラシをくわえたまま歩き回らない約束を徹底する。一人ひとりの磨き残しを保育者が丁寧に点検し、仕上げ磨きの大切さを保護者にも伝える。\n\n歯磨きを通して口の中が爽快になる心地よさを味わうことは、自らの体を大切にする自己肯定感や主体的な生活習慣の確立へと結びつく。小学校進学後も自立して食後の歯磨きを実践できる生活基盤を培うとともに、食育指導とも連動させることで、健康で豊かな食生活を送る生涯の礎となる。",
