    body: "児童虐待の早期発見における保育士の役割は、児童虐待防止法や保育所保育指針に明記された、子どもの最善の利益と生命を守るための法的義務である。乳幼児は自ら被害を訴えることが困難であるため、日常的に子どもと濃密に関わる保育士は、虐待の兆候を見逃さない早期発見の最前線として極めて重要な位置にある。\n\n日々の登降園時や着替え、排せつの際に、不自然な打撲痕や火傷、衣服の不潔さ、極端な体重減少など身体的兆候を細やかに確認する。同時に、過度におびえる、感情の起伏が激しいなどの情緒的変化や、保護者の拒否的な言動を客観的に記録する。虐待が疑われる場合は園長に報告し、児童相談所等へ速やかに通告する。\n\n通告後も関係機関と緊密に連携し、子どもに安全基地としての温かな保育環境を提供し続けることが求められる。家庭を孤立させず多角的な支援ネットワークにつなぐ取り組みは、子どもの尊厳を回復させ、将来にわたる健全な発達と学校生活への確かな歩みを保障する基盤となる。",
