    body: "特別な配慮を要する幼児の加配保育士配置は、障害者権利条約や子ども・子育て支援新制度に基づく、インクルーシブ保育を具現化するための人員配置事業である。集団生活において特別な援助を必要とする子どもに対し、個別的な配慮と集団参加の両立を保障し、すべての子どもの教育・保育を受ける権利を支える。\n\n加配保育士は、対象児の感覚の過敏さや行動特性を深く理解し、活動の切り替え時の個別支援や危険防止の環境整備を担う。単に対象児に付き添うだけでなく、クラス担任と連携しながら、周囲の友だちとの自然な関わりを仲立ちし、集団全体の活動が円滑に深まるよう柔軟に立ち位置や援助の度合いを調整する。\n\n適切な人的配置のもとで成功体験を重ねることは、配慮を要する子どもの自己肯定感と主体的な社会性を豊かに育む。同時に、多様な友だちと共に育つ経験は周囲の子どもたちにも共生社会の豊かな感覚を培い、小学校の特別支援教育や通常学級への円滑な接続を支える強力な基盤となる。",
