    body: "食物アレルギー除去食・代替食の安全管理は、保育所におけるアレルギー対応ガイドライン等に準拠し、子どもの生命と健康を守りながら安心な食生活を保障する重要施策である。誤食による重篤な事故を根絶するため、医師の生活管理指導表に基づいた科学的かつ組織的な管理が義務づけられている。\n\n給食室では専用の調理器具や食器を用い、混入を防ぐ個別調理を行う。配膳時には個別トレイに子どもの氏名と原因食材を明記した食札を立て、調理員と保育士による複数名での指差し確認を徹底する。専用の固定席を配置し、他児からの食物の受け渡しを防ぎながら、子どもが疎外感を感じないよう自然に会話を見守る。\n\n安全な食環境の確立は、子どもが給食を楽しみ、意欲的に食事に向き合う豊かな食育の基礎を形成する。食物アレルギーに対する正しい理解と自己管理の意識を幼少期から培うことは、小学校給食への安全な移行を確実に支え、生涯にわたって自らの健康を主体的に管理する態度へとつながる。",
