    body: "園庭環境の構成は、幼稚園教育要領や保育所保育指針が掲げる「環境を通して行う教育」の中核をなす実践である。子どもの運動能力の低下が指摘される現代において、固定遊具の機能的安全性と、子どもの発想で自由に変化させられる可動素材の可変性を有機的に組み合わせ、豊かな遊びと身体発達を促す設計が求められる。\n\n園庭には、登る・ぶら下がる等の基本動作を促す固定遊具を安全領域を確保して配置する。同時に、子どもが自ら運んで組み立てられるケース、木製パレット、板、タイヤなどの可動素材を豊富に用意する。保育者は安全点検を怠らず、子ども自身が場を作り変える試行錯誤を温かく見守り援助する。\n\n素材を工夫して基地作りやルールのある遊びへと発展させる経験は、子どもの創造力、問題解決力、仲間との協同性を飛躍的に高める。身体を力いっぱい動かす快感と仲間と協働して成し遂げる達成感は、小学校の体育科や生活科への滑らかな接続を支え、生涯にわたる主体的で健康的な活動意欲の基礎を培う。",
