    body: "預かり保育は、幼稚園や認定こども園において正規の教育課程に係る教育時間の前後や長期休業期間に園児を預かる教育活動である。共働き世帯の増加や女性の就業継続に対応する子ども・子育て支援新制度の重要施策として拡充され、幼稚園の選択肢を広げる役割を担っている。\n\n実施にあたっては、長時間の集団生活による疲労を考慮し、静かな休息の場や家庭的な温かい雰囲気の環境を構成する。専任の担当者を配置し、異年齢での自由な遊びや軽食の提供、季節の遊びを取り入れながら、子どもが緊張を解いて主体的に過ごせるよう手厚く援助する。\n\n保護者が安心して働き続けられる基盤を提供するとともに、子どもの育ちにとっても異年齢の交流や新たな遊びを深める貴重な生活の場となる。幼児教育の質の維持と家庭の就業支援を両立させ、地域の多様な子育て需要に柔軟に応える重要な役割を果たしている。",
