    body: "自然災害や不審者侵入に備える園の危機管理は、突発的な災害や犯罪から園児の生命と安全を最優先で守るための組織的マネジメント体制である。学校保健安全法や安全管理マニュアルに基づき、すべての幼稚園・保育所において計画的な予防対策と訓練の実施が義務づけられている。\n\n園内では、転倒防止器具の設置や避難経路の確保、防犯カメラや非常通報装置の点検を日常的に行う。毎月実施する避難訓練では、地震、火災、水害、不審者侵入など多様な状況を想定し、子どもが放送や保育者の指示を聞いて素早く机の下に隠れたり避難したりする行動を指導する。\n\n保育者自身が自衛・避難の役割分担を熟知し、地域や保護者との引き渡し訓練を定期的に行うことが不可欠である。幼児期から自らの命を守る基礎的な安全意識を養うとともに、地域全体で子どもを守る重層的な危機管理体制を築くことが強く求められている。",
