    body: "フロアブック・アプローチは、スコットランドのクレア・ウォーデンによって開発された、子どもの声や思考の道筋を協同的に記録・展開する教育実践手法である。床の上に置かれた大型の白紙台帳を子どもたちと保育者が囲み、子どもたちの気づきや対話をリアルタイムで可視化しながら、探究の深化を図る探究型カリキュラムの土台として考案された。\n\n実践では、散歩先での発見や日常の疑問について子ども同士が話し合い、保育者は子どもの言葉をそのまま大きな本に書き留めたり、描いた絵や拾った落ち葉、写真を貼り付けたりする。子どもたちは過去のページをめくって振り返り、「次はどう実験してみようか」と新たな課題を設定し、集団思考を深めていく。\n\nこの記録活動は、幼児教育におけるドキュメンテーションの発展形として機能し、子どもの思考力の可視化と自己効力感を大きく高める。幼児教育要領が掲げる「思考力の芽生え」や「言葉による伝え合い」を豊かな探究活動へと結びつける手法として、近年国際的に注目されている。",
